"use client";

import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import { loadFont } from "@remotion/google-fonts/SchibstedGrotesk";
import type React from "react";
import { useId } from "react";
import { AbsoluteFill, Easing, interpolate, interpolateColors } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_AFTER,
  DEFAULT_BEFORE,
  savedOf,
  segmentsOf,
  type TimeBreakdownElementId,
  timeBreakdownTimeline,
} from "./timeline";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const manrope = loadManrope("normal", {
  weights: ["500", "600"],
  subsets: ["latin"],
});

const REMOCN_R_PATH =
  "M 0.01 0.81 C 0.01 1.73, 0.36 2.79, 1.09 4.13 C 4.91 11.04, 13.45 17.16, 21.7 18.9 C 22.94 19.16, 23.18 19.16, 51.39 19.27 C 76.07 19.36, 80.02 19.4, 81.32 19.57 C 89.89 20.69, 96.2 24.68, 99.38 31.01 C 103.19 38.56, 102.53 50.1, 97.91 57.07 C 94.66 61.96, 89.68 64.99, 83.26 66 C 82.81 66.07, 70.18 66.83, 55.2 67.69 C 24.82 69.43, 27.03 69.23, 24.18 70.4 C 19.9 72.15, 14.84 75.7, 10.65 79.89 C 4.86 85.68, 1.3 91.91, 0.25 98.13 C 0.12 98.85, 0.08 103.13, 0.04 116.66 L 0 134.26 9.5 134.26 L 19 134.26 19.05 119.41 C 19.1 103.27, 19.08 103.82, 19.82 101.04 C 21.79 93.65, 27.86 88.75, 36.45 87.63 C 37.23 87.53, 39.41 87.5, 43.57 87.53 C 50.12 87.59, 50.75 87.65, 53.22 88.45 C 56.61 89.56, 59.67 91.86, 62.02 95.07 C 62.52 95.76, 69.35 103.85, 77.2 113.07 C 85.04 122.28, 91.63 130.04, 91.85 130.32 C 92.07 130.59, 92.5 131.34, 92.82 131.97 C 93.52 133.35, 94.11 133.93, 95.06 134.13 C 95.5 134.23, 98.97 134.26, 106.36 134.23 L 117.01 134.19 100.82 113.07 C 91.91 101.45, 84.52 91.78, 84.39 91.57 C 83.36 89.89, 83.66 87.53, 85.09 86 C 85.79 85.25, 86.36 84.94, 88.07 84.38 C 96.18 81.72, 104.15 76.62, 109.97 70.36 C 120.59 58.93, 124.06 44.32, 119.44 30.43 C 114.59 15.81, 101.93 4.02, 87.64 0.83 C 83.93 0.01, 88.09 0.08, 41.85 0.04 L 0.01 0 0.01 0.81 Z";

/** Full logo as on remocn.dev: R mark (0.76em tall, baseline-aligned) + "emocn" in Manrope 600, tracking-tight. */
function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

// gradients.sh "aurora": soft curtains over a near-black base, plus the
// horizontal band. Lives only inside the freed-time panel.
const BRAND_TAIL = /remocn$/i;

const AURORA = ["#A0F0C8", "#3FB5A3", "#5147B6", "#B25C9C"];

function auroraFill(base: string, drift: number) {
  const n = AURORA.length;
  const curtains = AURORA.map((c, i) => {
    const x = 12 + (76 * i) / (n - 1) + Math.sin(drift + i * 1.9) * 4;
    const h = 150 + Math.cos(drift * 0.8 + i * 1.3) * 20;
    return `radial-gradient(34% ${h}% at ${x}% 100%, color-mix(in oklab, ${c} 80%, transparent) 0%, transparent 72%)`;
  });
  return [
    ...curtains,
    `linear-gradient(180deg, color-mix(in oklab, ${AURORA[0]} 18%, transparent) 0%, transparent 60%)`,
    base,
  ].join(", ");
}

export interface TimeSegment {
  label: string;
  value: number;
}

export interface TimeBreakdownProps {
  before?: TimeSegment[];
  after?: TimeSegment[];
  title?: string;
  beforeLabel?: string;
  afterLabel?: string;
  caption?: string;
  accent?: string;
  /** Text color of the labels and figures; overrides the theme. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the copy. Load it yourself; Schibsted Grotesk by default. */
  fontFamily?: string;
  /** Corner radius of the bar, in px at 720p. */
  radius?: number;
  /** Frames between characters of the hero figure as it rolls in. */
  stagger?: number;
  /** Replaces the remocn mark when `afterLabel` ends in "remocn". */
  logo?: React.ReactNode;
  grain?: boolean;
  /** Size of the chart, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches the title, the bar's reveal, split and
   * collapse, the heading switch, the camera drift and the hero figure, by
   * the ids in `./timeline`. Frames on the scene timeline, after `delay` and
   * `speed`.
   */
  timing?: Timing<TimeBreakdownElementId>;
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    faint: "#5A595F",
    hair: "rgba(255,255,255,0.3)",
    base: "#4A494F",
    tones: ["#77767C", "#4E4D53", "#36353A", "#2A292E"],
    stage: "rgba(255,255,255,0.05)",
    aurora: "#03050B",
    auroraEdge: "rgba(255,255,255,0.14)",
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    faint: "#A3A099",
    hair: "rgba(18,18,20,0.32)",
    base: "#BDBBB4",
    tones: ["#8E8C86", "#B3B1AA", "#CFCDC6", "#DEDCD6"],
    stage: "rgba(255,255,255,0.7)",
    aurora: "#FFFFFF",
    auroraEdge: "rgba(18,18,20,0.10)",
    grain: 0.045,
  },
} as const;

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={23}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function Hero({
  text,
  t,
  size,
  color,
  fontFamily,
  stagger,
  roll,
}: {
  text: string;
  t: number;
  size: number;
  color: string;
  fontFamily: string;
  stagger: number;
  roll: number;
}) {
  return (
    <div
      style={{
        display: "flex",
        whiteSpace: "pre",
        fontFamily,
        fontWeight: 400,
        fontSize: size,
        lineHeight: 1,
        letterSpacing: "-0.045em",
        fontVariantNumeric: "tabular-nums",
        color,
      }}
    >
      {Array.from(text).map((ch, i) => {
        const p = interpolate(t, [i * stagger, i * stagger + roll], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        return (
          <span
            key={i}
            style={{
              display: "inline-block",
              overflow: "hidden",
              paddingBottom: size * 0.06,
              marginBottom: -size * 0.06,
            }}
          >
            <span
              style={{
                display: "inline-block",
                transform: `translateY(${(1 - p) * 0.7 * size}px)`,
                opacity: interpolate(p, [0, 0.4], [0, 1], CLAMP),
              }}
            >
              {ch}
            </span>
          </span>
        );
      })}
    </div>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function TimeBreakdown(props: TimeBreakdownProps) {
  const {
    before = DEFAULT_BEFORE,
    after = DEFAULT_AFTER,
    title = "Where the time goes",
    beforeLabel = "Before",
    afterLabel = "With remocn",
    caption = "less time per video",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = sans,
    radius: corner = 12,
    logo,
    grain = true,
    scale = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const frame = useSceneFrame();
  const t = Math.max(0, frame - delay) * speed;
  const { width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    timeBreakdownTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const titleEl = tl.get("title");
  const barEl = tl.get("bar");
  const driftEl = tl.get("drift");
  const splitEl = tl.get("split");
  const switchEl = tl.get("switch");
  const collapseEl = tl.get("collapse");
  const heroEl = tl.get("hero");
  const u = Math.min(width / 1280, height / 720);
  const th = THEMES[theme];
  const fg = ink ?? th.fg;
  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? th.bg);
  const clipId = `h${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  const segs = segmentsOf(before, after);
  const totalBefore = segs.reduce((s, x) => s + x.from, 0) || 1;
  const saved = savedOf(segs);
  const focus = segs.reduce(
    (best, s, i) =>
      s.from - s.to > segs[best].from - segs[best].to ? i : best,
    0,
  );

  const margin = width * 0.085;
  const x0 = margin;
  const barW = width - margin * 2;
  const barH = 84 * u;
  const barTop = height * 0.52;
  const radius = corner * u;

  const reveal = interpolate(t, [barEl.start, barEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const split = interpolate(t, [splitEl.start, splitEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const gap = 6 * u * split;
  const sw = interpolate(t, [switchEl.start, switchEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const T_COLLAPSE = collapseEl.start;
  const tint = interpolate(
    t,
    [
      T_COLLAPSE + collapseEl.beat("tint"),
      T_COLLAPSE + collapseEl.beat("tintEnd"),
    ],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_IO,
    },
  );
  const c = interpolate(t, [T_COLLAPSE, collapseEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const usable = barW - gap * (segs.length - 1);
  const unitW = usable / totalBefore;
  const geom: { x: number; w: number; v: number }[] = [];
  let cursor = x0;
  segs.forEach((s) => {
    const v = s.from + (s.to - s.from) * c;
    const w = v * unitW;
    geom.push({ x: cursor, w, v });
    cursor += w + gap;
  });
  const usedEnd = cursor - gap;
  const freedX = usedEnd + gap;
  const freedW = Math.max(0, x0 + barW - freedX);
  const freedIn = interpolate(
    t,
    [
      T_COLLAPSE + collapseEl.beat("freedAt"),
      T_COLLAPSE + collapseEl.beat("freedEnd"),
    ],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_IO,
    },
  );
  const finalFreedX =
    x0 + segs.reduce((s, x) => s + x.to * unitW, 0) + 6 * u * segs.length;

  const labelEnds: number[] = [];
  const labelX = geom.map((g, i) => {
    const min = i > 0 ? labelEnds[i - 1] + 18 * u : g.x;
    const x = Math.max(g.x, min);
    // Schibsted Grotesk advances: ~0.53em lowercase at 18px, ~0.6em digits at 42px.
    const nameW = segs[i].label.length * 0.53 * 18 * u;
    const pctW =
      (String(Math.round((g.v / totalBefore) * 100)).length + 1) * 0.6 * 42 * u;
    labelEnds.push(x + Math.max(nameW, pctW));
    return x;
  });

  const heroT = t - heroEl.start;
  const heroSize = Math.min(160 * u, width * 0.125);
  const capIn = interpolate(
    heroT,
    [heroEl.beat("capAt"), heroEl.beat("capEnd")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );
  const bracketIn = interpolate(
    heroT,
    [heroEl.beat("bracketAt"), heroEl.beat("bracketEnd")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_IO,
    },
  );
  const titleIn = interpolate(t, [titleEl.start, titleEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const driftAt = (f: number) =>
    interpolate(
      Math.max(0, f - delay) * speed,
      [driftEl.start, driftEl.end],
      [1.025, 1],
      {
        ...CLAMP,
        easing: EASE_IO,
      },
    );
  const drift = driftAt(frame);
  // The drift's ease is so flat at its ends that a progress test would keep
  // the tilt on while nothing visibly moves; weigh the scale step by the
  // distance from the origin to the frame's edge instead.
  const reach = Math.max(width, height) / 2;
  const drifting =
    Math.abs(driftAt(frame + 1) - drift) * reach > 1e-3 ||
    Math.abs(drift - driftAt(frame - 1)) * reach > 1e-3;

  const bracketY = barTop - 22 * u;
  const auroraDrift = interpolate(
    t,
    [T_COLLAPSE, T_COLLAPSE + collapseEl.beat("auroraEnd")],
    [0, 1.6],
    CLAMP,
  );
  const tick = 8 * u;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 70% 70% at 40% 45%, ${th.stage}, transparent 75%)`,
        }}
      />
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            transform: `scale(${drift})${glide(drifting)}`,
            transformOrigin: "50% 55%",
          }}
        >
          <div
            style={{
              position: "absolute",
              left: x0,
              top: height * 0.2,
              fontFamily,
              fontSize: 22 * u,
              fontWeight: 500,
              color: th.muted,
              whiteSpace: "nowrap",
              opacity: titleIn,
              transform: `translateY(${(1 - titleIn) * 8 * u}px)`,
            }}
          >
            {title}
          </div>

          <div
            style={{
              position: "absolute",
              left: x0,
              top: barTop - 70 * u,
              width: barW * 0.45,
              height: 40 * u,
              opacity: titleIn,
            }}
          >
            {[beforeLabel, afterLabel].map((lbl, i) => {
              const a =
                i === 0
                  ? interpolate(sw, [0, 0.6], [1, 0], CLAMP)
                  : interpolate(sw, [0.35, 1], [0, 1], CLAMP);
              const y = i === 0 ? -sw * 14 * u : (1 - sw) * 14 * u;
              return (
                <div
                  key={lbl}
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    height: 40 * u,
                    display: "flex",
                    alignItems: "center",
                    gap: 10 * u,
                    opacity: a,
                    transform: `translateY(${y}px)`,
                    filter: a < 0.98 ? `blur(${(1 - a) * 4 * u}px)` : undefined,
                    fontFamily,
                    fontSize: 30 * u,
                    fontWeight: 400,
                    letterSpacing: "-0.025em",
                    color: fg,
                    whiteSpace: "nowrap",
                  }}
                >
                  {i === 1 && BRAND_TAIL.test(lbl) ? (
                    <>
                      {lbl.replace(BRAND_TAIL, "").trim()}
                      <span style={{ marginLeft: 2 * u, marginTop: 2 * u }}>
                        {logo ?? <RemocnLogo fontSize={31 * u} color={fg} />}
                      </span>
                    </>
                  ) : (
                    <>
                      {i === 1 ? (
                        <span
                          style={{
                            width: 10 * u,
                            height: 10 * u,
                            borderRadius: "50%",
                            background: accent,
                          }}
                        />
                      ) : null}
                      {lbl}
                    </>
                  )}
                </div>
              );
            })}
          </div>

          {freedW > 1 ? (
            <div
              style={{
                position: "absolute",
                left: freedX,
                top: barTop,
                width: freedW,
                height: barH,
                borderRadius: radius,
                overflow: "hidden",
                opacity: freedIn,
                background: auroraFill(th.aurora, auroraDrift),
                boxShadow: `inset 0 0 0 ${Math.max(1, u)}px ${th.auroraEdge}`,
              }}
            />
          ) : null}

          <svg
            width={width}
            height={height}
            style={{ position: "absolute", inset: 0, overflow: "visible" }}
            aria-hidden
          >
            <defs>
              <clipPath id={`${clipId}c`}>
                <rect
                  x={x0}
                  y={barTop - 4 * u}
                  width={barW * reveal}
                  height={barH + 8 * u}
                />
              </clipPath>
            </defs>

            <g clipPath={`url(#${clipId}c)`}>
              {geom.map((g, i) => {
                const tone = th.tones[Math.min(i, th.tones.length - 1)];
                const split3 = interpolateColors(
                  split,
                  [0, 1],
                  [th.base, tone],
                );
                const fill =
                  i === focus
                    ? interpolateColors(tint, [0, 1], [split3, accent])
                    : split3;
                const first = i === 0;
                const last = i === geom.length - 1;
                const rl = first ? radius : radius * split * 0.35;
                const rr = last ? radius : radius * split * 0.35;
                const w = Math.max(g.w, 2 * u);
                const rlc = Math.min(rl, w / 2);
                const rrc = Math.min(rr, w / 2);
                const x = g.x;
                const y = barTop;
                const h = barH;
                const d = [
                  `M ${x + rlc} ${y}`,
                  `H ${x + w - rrc}`,
                  `Q ${x + w} ${y} ${x + w} ${y + rrc}`,
                  `V ${y + h - rrc}`,
                  `Q ${x + w} ${y + h} ${x + w - rrc} ${y + h}`,
                  `H ${x + rlc}`,
                  `Q ${x} ${y + h} ${x} ${y + h - rlc}`,
                  `V ${y + rlc}`,
                  `Q ${x} ${y} ${x + rlc} ${y}`,
                  "Z",
                ].join(" ");
                return <path key={segs[i].label} d={d} fill={fill} />;
              })}
            </g>

            {saved > 0 ? (
              <g
                opacity={bracketIn}
                stroke={th.hair}
                strokeWidth={Math.max(1, 1.25 * u)}
              >
                <line
                  x1={finalFreedX}
                  x2={finalFreedX + (x0 + barW - finalFreedX) * bracketIn}
                  y1={bracketY}
                  y2={bracketY}
                />
                <line
                  x1={finalFreedX}
                  x2={finalFreedX}
                  y1={bracketY - tick}
                  y2={bracketY + tick}
                />
                <line
                  x1={x0 + barW}
                  x2={x0 + barW}
                  y1={bracketY - tick}
                  y2={bracketY + tick}
                  opacity={interpolate(bracketIn, [0.85, 1], [0, 1], CLAMP)}
                />
              </g>
            ) : null}
          </svg>

          {geom.map((g, i) => {
            const seg = tl.get(`segment:${i}`);
            const a = interpolate(t, [seg.start, seg.end], [0, 1], {
              ...CLAMP,
              easing: EASE_OUT,
            });
            const countIn = interpolate(
              t,
              [seg.start, seg.start + seg.beat("count")],
              [0, 1],
              { ...CLAMP, easing: Easing.bezier(0.22, 1, 0.36, 1) },
            );
            const isFocus = i === focus;
            const pct = Math.round((g.v / totalBefore) * 100 * countIn);
            return (
              <div
                key={segs[i].label}
                style={{
                  position: "absolute",
                  left: labelX[i],
                  top: barTop + barH + 20 * u,
                  display: "flex",
                  flexDirection: "column",
                  gap: 2 * u,
                  opacity: a,
                  transform: `translateY(${(1 - a) * 10 * u}px)`,
                  whiteSpace: "nowrap",
                }}
              >
                <span
                  style={{
                    fontFamily,
                    fontSize: 18 * u,
                    fontWeight: 500,
                    color: isFocus
                      ? interpolateColors(tint, [0, 1], [th.muted, accent])
                      : th.muted,
                  }}
                >
                  {segs[i].label}
                </span>
                <span
                  style={{
                    fontFamily,
                    fontSize: 42 * u,
                    fontWeight: 400,
                    letterSpacing: "-0.035em",
                    fontVariantNumeric: "tabular-nums",
                    color: fg,
                  }}
                >
                  {pct}%
                </span>
              </div>
            );
          })}

          {saved > 0 ? (
            <div
              style={{
                position: "absolute",
                left: finalFreedX - heroSize * 0.04,
                top: bracketY - 22 * u,
                transform: "translateY(-100%)",
                display: "flex",
                alignItems: "baseline",
                gap: 18 * u,
              }}
            >
              <Hero
                text={`${saved}%`}
                t={heroT}
                size={heroSize}
                color={fg}
                fontFamily={fontFamily}
                stagger={heroEl.beat("stagger")}
                roll={heroEl.beat("roll")}
              />
              <span
                style={{
                  fontFamily,
                  fontSize: 32 * u,
                  fontWeight: 400,
                  letterSpacing: "-0.02em",
                  color: th.muted,
                  whiteSpace: "nowrap",
                  opacity: capIn,
                  transform: `translateY(${(1 - capIn) * 10 * u}px)`,
                }}
              >
                {caption}
              </span>
            </div>
          ) : null}
        </AbsoluteFill>
      </ScaleLayer>

      {transparent ? null : (
        <AbsoluteFill
          style={{
            background: `radial-gradient(ellipse 85% 85% at 50% 50%, transparent 60%, ${stage} 100%)`,
            opacity: 0.55,
          }}
        />
      )}
      {grain ? <Grain opacity={th.grain} /> : null}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The title and the bar coming in, the bar splitting into its segments, the
// label switching to "after", the segments collapsing to their new sizes as
// the freed time opens up, then the hero figure rolling in under its
// bracket. Frames on the 30 fps scene timeline, after `delay` and `speed`.
// The ids are public: a saved `timing` prop refers to them.

export type TimeBreakdownElementId =
  | "title"
  | "bar"
  | "drift"
  | "split"
  | `segment:${number}`
  | "switch"
  | "collapse"
  | "hero";

interface Segment {
  label: string;
  value: number;
}

export interface TimeBreakdownTimingProps {
  before?: Segment[];
  after?: Segment[];
  /** Frames between characters of the hero figure as it rolls in. */
  stagger?: number;
}

export const DEFAULT_BEFORE = [
  { label: "Editing", value: 62 },
  { label: "Rendering", value: 24 },
  { label: "Export", value: 14 },
];

export const DEFAULT_AFTER = [
  { label: "Editing", value: 6 },
  { label: "Rendering", value: 24 },
  { label: "Export", value: 14 },
];

const T_SPLIT = 22;
const T_SWITCH = 66;
const T_COLLAPSE = 74;
const COLLAPSE_LEN = 36;
const T_DONE = T_COLLAPSE + COLLAPSE_LEN;
const ROLL = 22;

/** The segments as they go from `before` to `after`, at most five. */
export function segmentsOf(before: Segment[], after: Segment[]) {
  return before.slice(0, 5).map((b, i) => ({
    label: b.label,
    from: Math.max(0, b.value),
    to: Math.max(0, after[i]?.value ?? b.value),
  }));
}

/** The share of the time saved, in whole percent. */
export function savedOf(segs: ReturnType<typeof segmentsOf>) {
  const totalBefore = segs.reduce((s, x) => s + x.from, 0) || 1;
  const totalAfter = segs.reduce((s, x) => s + x.to, 0);
  return Math.max(0, Math.round((1 - totalAfter / totalBefore) * 100));
}

// `title` and `bar` come in (from before the scene's first frame). `drift` is
// the slow camera push over the whole build. `split` opens the gaps between
// segments; `segment:<i>` (a chain after the split) brings in segment `i`'s
// label and counts its share up over `count`. `switch` swaps the heading to
// "after". `collapse` shrinks the
// segments to their new sizes: they tint from `tint` to `tintEnd`, the freed
// panel fades in from `freedAt` to `freedEnd`, and its aurora drifts until
// `auroraEnd`. `hero` (following the collapse) rolls the figure in, one
// character every `stagger` frames, each over `roll`; its bracket draws from
// `bracketAt` to `bracketEnd` and the caption from `capAt` to `capEnd`.
export const timeBreakdownTimeline = defineTimeline<
  TimeBreakdownElementId,
  TimeBreakdownTimingProps
>(({ before = DEFAULT_BEFORE, after = DEFAULT_AFTER, stagger = 3 }) => {
  const hero = `${savedOf(segmentsOf(before, after))}%`;
  const chars = Array.from(hero).length;
  const elements: TimelineElement<TimeBreakdownElementId>[] = [
    { id: "title", lane: "Copy", label: "Title", start: -6, length: 22 },
    { id: "bar", lane: "Bar", label: "Bar", start: -4, length: 28 },
    {
      id: "drift",
      lane: "Camera",
      label: "Drift",
      start: 0,
      length: T_DONE + 60,
    },
    { id: "split", lane: "Bar", label: "Split", start: T_SPLIT, length: 18 },
    ...segmentsOf(before, after).map(
      (seg, i): TimelineElement<TimeBreakdownElementId> => ({
        id: `segment:${i}`,
        lane: "Segments",
        label: seg.label,
        start: T_SPLIT + 6 + i * 4,
        length: 20,
        follows: i > 0 ? `segment:${i - 1}` : "split",
        beats: { count: 28 },
      }),
    ),
    {
      id: "switch",
      lane: "Copy",
      label: "After",
      start: T_SWITCH,
      length: 14,
    },
    {
      id: "collapse",
      lane: "Bar",
      label: "Collapse",
      start: T_COLLAPSE,
      length: COLLAPSE_LEN,
      beats: {
        tint: -4,
        tintEnd: 6,
        freedAt: 6,
        freedEnd: 22,
        auroraEnd: COLLAPSE_LEN + 80,
      },
    },
    {
      id: "hero",
      lane: "Copy",
      label: hero,
      start: T_DONE - 4,
      length: Math.max(32, (chars - 1) * stagger + ROLL),
      follows: "collapse",
      beats: {
        stagger,
        roll: ROLL,
        bracketAt: -6,
        bracketEnd: 18,
        capAt: 12,
        capEnd: 32,
      },
    },
  ];
  return elements;
});
